function laserShots(panels) {
  const candidates = [...new Set(panels.flat())];
  const chosen = [];
  const marksAll = () => panels.every(([left, right]) => chosen.some((x) => left <= x && x <= right));
  const search = (start, remaining) => {
    if (remaining === 0) return marksAll();
    for (let i = start; i + remaining <= candidates.length; i++) {
      chosen.push(candidates[i]);
      const found = search(i + 1, remaining - 1);
      chosen.pop();
      if (found) return true;
    }
    return false;
  };
  for (let shots = 0; shots <= candidates.length; shots++) {
    if (search(0, shots)) return shots;
  }
  return -1;
}

