function laserShots(panels) {
  const sorted = panels.map((panel) => [panel[0], panel[1]]);
  sorted.sort((a, b) => a[1] - b[1]);
  const chain = new Array(sorted.length).fill(1);
  let best = 0;
  for (let i = 0; i < sorted.length; i++) {
    for (let j = 0; j < i; j++) {
      if (sorted[j][1] < sorted[i][0] && chain[j] + 1 > chain[i]) chain[i] = chain[j] + 1;
    }
    best = Math.max(best, chain[i]);
  }
  return best;
}

function laserShots(panels) {
  const byRightEdge = panels.map((panel) => [panel[0], panel[1]]);
  byRightEdge.sort((a, b) => a[1] - b[1]);
  let shots = 0;
  let lastShot = -Infinity;
  for (const [left, right] of byRightEdge) {
    if (left > lastShot) {
      shots++;
      lastShot = right;
    }
  }
  return shots;
}
